EXISTING_HOME_CARD = {
 "app/src/main/java/com/android/purebilibili/core/ui/transition/VideoCardTransitionBackgroundPolicy.kt",
 "app/src/main/java/com/android/purebilibili/core/ui/blur/RecoverableVisualEffects.kt",
}
REFERENCE_ONLY = "DesktopHomeMatchedDockVisibilityReference.kt"

def _assemble(repo, work):
    repo=Path(repo).resolve();work=Path(work).resolve()
    scope={"HERE":work,"REPO":repo,"MAIN":repo,"PREFIX":chr(92)*2+"?"+chr(92),"_SELECTED":_SELECTED,"_advance_home_undo":_advance_home_undo,"_brand_error_consumer":_brand_error_consumer,"_brand_shared_helpers":_brand_shared_helpers,"__name__":"home_page_selected"}
    exec(_HEADER,scope)
    for row in _SELECTED:
        actual=hashlib.sha256(scope["read"](repo/row["path"]).encode()).hexdigest()
        if actual!=row["sha256LF"]:raise ValueError("Home selected source identity changed: "+row["path"])
    exec(_BODY,scope);exec(_ADDITIONS,scope);exec("import textwrap",scope);exec(_SETTINGS,scope)
    return scope

def existing_home_card_body(repo, path):
    """Called by the existing sole home-full-card producer, never emitted a second time."""
    if path not in EXISTING_HOME_CARD:raise ValueError(path)
    with tempfile.TemporaryDirectory(prefix="bilipai-home-card-source-") as temporary:
        scope=_assemble(repo,temporary)
        rows=json.loads(scope["read"](Path(temporary)/"producer-inventory.json"))
        row=next(r for r in rows if r["path"]==path)
        return scope["read"](Path(temporary)/row["generated"])

def _bind_preview_subject(text):
    # Android can keep AnimatedVisibility composed while the subject changes. The native
    # preview owns a source/coroutine, so preserve the original caller but scope its remembered
    # URL/player effect to the actual immutable BVID/CID subject. Epoch is Root's outer key.
    opening="            if (item != null) {\n                com.android.purebilibili.feature.home.components.VideoPreviewDialog("
    closing="                hazeState = hazeState\n            )\n            }\n        }\n        } // Unified header/feed depth snapshot"
    assert text.count(opening)==1 and text.count(closing)==1
    text=text.replace(opening,"            if (item != null) {\n                key(item.bvid, item.cid) {\n                com.android.purebilibili.feature.home.components.VideoPreviewDialog(")
    return text.replace(closing,"                hazeState = hazeState\n            )\n                } // Native preview subject lifetime\n            }\n        }\n        } // Unified header/feed depth snapshot")

def generate(repo, output, standalone=False):
    output=Path(output).resolve();written=[];home_load_audits=[]
    with tempfile.TemporaryDirectory(prefix="bilipai-original-home-") as temporary:
        scope=_assemble(repo,temporary);work=Path(temporary)
        rows=json.loads(scope["read"](work/"producer-inventory.json"))
        for source in work.rglob("*.kt"):
            if source.name==REFERENCE_ONLY:continue
            row=next((r for r in rows if r.get("generated")==source.relative_to(work).as_posix()),None)
            if row and row["path"] in EXISTING_HOME_CARD and not standalone:continue
            relative=source.relative_to(work/"prepared")
            if relative.parts[0] not in ("generated","manual"):continue
            target=output/Path(*relative.parts[1:])
            body=scope["read"](source)
            if row and row["path"]=="app/src/main/java/com/android/purebilibili/feature/home/HomeScreen.kt":body=_bind_preview_subject(body)
            body=home_page_delta(repo,target.name,body,home_load_audits)
            scope["write"](target,body);written.append(target)
        output.mkdir(parents=True,exist_ok=True)
        scope["write"](output/"home-page-producer-inventory.json",json.dumps(rows,ensure_ascii=False,indent=2)+"\n")
        scope["write"](output/"home-page-settings-selection.json",scope["read"](work/"settings-selection-evidence.json"))
        scope["write"](output/"home-page-v029-load-adaptations.json",json.dumps(dict(upstreamCommit="a4b77f894d0a2dd26c0b9fc144b8adb88ac05480",audits=home_load_audits),ensure_ascii=False,indent=2)+"\n")
    # Whole original UserAgreementPolicy is emitted only by prepareUpstreamSources.
    legacy_agreement=output/'com/android/purebilibili/feature/onboarding/UserAgreementPolicy.kt'
    if legacy_agreement.exists():
        assert not legacy_agreement.is_symlink() and legacy_agreement.resolve().is_relative_to(output.resolve())
        assert legacy_agreement.stat().st_size==363
        assert hashlib.sha256(legacy_agreement.read_bytes()).hexdigest()=="d5c863b0ff6cba03794b75788836a78d42d9390a94f5b7643f1923b49b795b5c"
        legacy_agreement.unlink()
    return written

if __name__=="__main__":
    parser=argparse.ArgumentParser();parser.add_argument("--repo",required=True);parser.add_argument("--output",required=True)
    parser.add_argument("--standalone",action="store_true");args=parser.parse_args()
    print("original Home outputs",len(generate(args.repo,args.output,args.standalone)))
